INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (104,1,'🐜🍉','夏天到了，一群小蚂蚁在草地上发现了一块大西瓜！"哇，好大的西瓜呀！"蚂蚁们开心地叫起来。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (104,2,'💪🐜','蚂蚁们试着搬西瓜，可是西瓜太大了，搬不动！一只蚂蚁说："我们大家一起推！"');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (104,3,'📢🐜','蚂蚁国王吹起小喇叭，喊来了一千只蚂蚁！大家排成长长的队伍，一起用力推西瓜。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (104,4,'🏔️🍉','蚂蚁们终于把西瓜搬回了家！蚂蚁洞里堆满了红红的西瓜肉，每只蚂蚁都分到了一大块。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (104,5,'😋🐜','蚂蚁们吃得肚子圆鼓鼓的，开心极了！剩下的西瓜皮该怎么办呢？');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (104,6,'🛝🍉','蚂蚁们把西瓜皮变成了滑滑梯！一只只小蚂蚁排着队滑下来，笑声传遍了整个蚂蚁王国。大家一起努力，什么都能做到！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (105,1,'🐷🐘','小猪和小象是最好的朋友！小猪总是开开心心的，小象总是有点小心翼翼。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (105,2,'🎉🐷','今天小猪想出一个好玩的游戏，小象有点害怕，但还是跟着小猪一起玩了起来。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (105,3,'🌧️😊','突然下起了大雨！小象用大耳朵给小猪挡雨，小猪说："有你真好！"');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (105,4,'🤗🐘','小猪摔倒了，小象赶紧跑过去扶起来。小猪笑着说："谢谢你，好朋友！"');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (105,5,'🎈🐷','小猪想飞上天，小象虽然觉得不可能，但还是帮忙想办法。两个好朋友一起努力，总是很开心。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (105,6,'❤️🐷🐘','不管做什么，有好朋友在身边就不害怕！小猪和小象拉着手说："我们永远是最好的朋友！"');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (106,1,'🐻😢','大熊总是欺负小动物们，抢走大家的玩具和零食。小兔子被抢走了胡萝卜，伤心地哭了。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (106,2,'😡🐰','小兔子鼓起勇气对大熊说："不要随便欺负我！这样是不对的！"大熊愣住了。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (106,3,'🤝🐻','其他小动物也站出来说："对，不可以欺负人！"大熊低下了头，觉得自己做错了。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (106,4,'💬🐻','大熊说："对不起，我不应该欺负你们。"原来大熊只是不知道怎么交朋友。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (106,5,'😊🐻🐰','小兔子说："我们可以一起玩呀！"大熊开心地笑了，原来做朋友比欺负人有趣多了。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (106,6,'❤️🤗','大家成了好朋友，一起分享玩具和零食。记住，被欺负了要勇敢说不，欺负别人是不对的！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (107,1,'🐶😠','小老虎总是命令小狗做这做那：\'去给我拿水！\'\'帮我背书包！\'小狗每天都很累。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (107,2,'😣🐶','小狗回到家，妈妈问：\'你为什么不开心？\'小狗说：\'小老虎总是命令我，我不想做了。\'');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (107,3,'💪🐶','妈妈说：\'你是自己的主人，不要随便让别人命令你。\'小狗想了想，决定勇敢说出来。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (107,4,'🗣️🐶','第二天小老虎又来命令小狗，小狗大声说：\'不要随便命令我！我们是朋友，不是主仆！\'');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (107,5,'😮🐯','小老虎很惊讶，没有人这样跟他说过话。他想了想说：\'对不起，我不应该命令你。\'');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (107,6,'🤝🐯🐶','小老虎学会了用请求代替命令，两个好朋友一起开心地玩耍。每个人都有说不的权利！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (108,1,'🐓🐢','公鸡和小乌龟是好朋友，虽然一个跑得快一个爬得慢，但他们总是一起散步聊天。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (108,2,'🐷🐰','小猪和小兔也是好朋友，小猪喜欢在泥里打滚，小兔喜欢在草地上蹦跳，他们互相分享快乐。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (108,3,'🎣🐢','小乌龟慢慢爬到河边，公鸡耐心地等着他。好朋友就是愿意等你，不催你。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (108,4,'🌧️🏠','下雨了，小猪邀请小兔到自己家里躲雨。好朋友就是在你需要的时候帮助你。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (108,5,'🎂🎉','今天是公鸡的生日，所有好朋友都来庆祝！每个朋友都带来了自己最拿手的礼物。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (108,6,'❤️👫','好朋友不一定要一样，不一样也能成为最好的朋友！重要的是互相尊重和关心。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (109,1,'🧒🎈','小朋友们来到游乐场，大家都想先玩滑梯！"我先！我先！"大家挤来挤去。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (109,2,'😟🧒','挤来挤去谁也玩不成，还有小朋友摔倒了。老师说："我们排好队，一个接一个好不好？"');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (109,3,'📏🧒','小朋友们排成一条整齐的队伍。第一个滑下来，第二个再上，一个接一个！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (109,4,'😊🧒','排好队后，每个小朋友都玩到了滑梯！不用挤也不用抢，大家都很开心。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (109,5,'🍦🧒','买冰淇淋的时候也要排队哦！先来的先买，后来的等一等，这样才公平。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (109,6,'🌟🧒','排队是一种礼貌，也是一种规则。排好队，一个接一个，大家都开心！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (110,1,'🐱🐿️🦆','猫、松鼠和鸭子是最好的朋友，他们一起住在一间小屋子里，每天一起做南瓜汤。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (110,2,'🥄🐱','猫切南瓜，松鼠搅汤，鸭子放盐，每个人都有自己的工作，做出来的南瓜汤是世界上最好喝的！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (110,3,'😤🦆','有一天鸭子想搅汤，松鼠不让！他们吵了起来，锅也翻了，汤也洒了。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (110,4,'🏃🦆','鸭子伤心地走了，松鼠和猫都很担心。没有鸭子，南瓜汤再也不好喝了。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (110,5,'🤗🐱🐿️','鸭子回来了！三个朋友抱在一起，决定轮流做不同的工作。原来每个人都有不同的本领。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (110,6,'🍲❤️','三个人一起做的南瓜汤，还是世界上最好喝的汤！好朋友吵架不可怕，重要的是和好和包容。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (111,1,'🐰🏠','小兔子想租一间新房子，可是房租太贵了，一只小兔子根本租不起。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (111,2,'🤔🐰','小兔子想啊想："如果我找好朋友一起住，大家一起分担房租就好了！"');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (111,3,'🦊🐰','小兔子找到了小狐狸和小松鼠，问他们愿不愿意一起租房。三个人一起就租得起了！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (111,4,'🧹🦊','搬进新家后，大家分工合作！小兔子打扫卫生，小狐狸做饭，小松鼠整理房间。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (111,5,'🎉🐰🦊🐿️','大家一起装饰新家，挂上漂亮的画，摆上软软的沙发。这就是团队的力量！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (111,6,'❤️🏠','一个人做不到的事情，团队一起就能做到！团结合作，什么困难都不怕。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (112,1,'🦍😢','大猩猩很孤独，他没有朋友。他想了一个办法：把友情租出去，每小时五块钱。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (112,2,'👧🦍','小女孩咪咪租了大猩猩的友情，他们一起玩捉迷藏、一起看书，开心极了！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (112,3,'⏰🦍','每次沙漏漏完，咪咪就要回家。大猩猩很舍不得，他开始期待下一次。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (112,4,'❤️🦍','渐渐地，大猩猩不再要咪咪的钱了。因为友情不是用钱能买的，而是用心换来的。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (112,5,'😟👧','有一天咪咪搬家了，大猩猩伤心极了。他终于明白，友情不能出租，要主动去寻找。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (112,6,'🤗🦍👫','大猩猩不再收钱了，他主动对大家说："我们一起玩吧！"很快他就有了很多朋友。友情是免费的！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (113,1,'🐀💒','老鼠村长要嫁女儿，他想把女儿嫁给世界上最厉害的人！谁是最厉害的呢？');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (113,2,'☀️☁️','老鼠觉得太阳最厉害，可太阳说他怕云遮住。云说他怕风吹走。风说他怕墙挡住。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (113,3,'🧱🐀','墙说他最怕老鼠打洞！原来绕了一圈，最厉害的还是老鼠自己呀！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (113,4,'🐀🎉','老鼠村长恍然大悟：世界上没有谁是绝对最厉害的，每个人都有自己的长处。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (113,5,'💍🐀','老鼠姑娘嫁给了隔壁勇敢善良的小老鼠，他们一起快乐地生活。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (113,6,'❤️🎊','不必追求最厉害的人，找到真心对你好的才是最重要的。每个人都是独一无二的！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (114,1,'🐕🐄🦁','草地上有很多动物：小狗、奶牛、狮子、兔子、大象、猴子……你能记住它们在哪里吗？');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (114,2,'😄❓','大家笑眯眯的，突然——谁藏起来了？仔细看，有一个动物不见了！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (114,3,'😢❓','又有一只动物藏起来了！这次是谁呢？只有一只动物在哭，其他都笑嘻嘻的。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (114,4,'😤❓','又有动物藏起来了！这次谁在生气？快找找看，少了哪一只动物？');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (114,5,'😴❓','哎呀，有动物在打瞌睡！又有谁藏起来不见了？越到后面越难找哦！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (114,6,'🎉👀','所有藏起来的动物都出来啦！这个游戏锻炼了你的观察力和记忆力，真棒！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (115,1,'🏠👦','小男孩收到一封信，邀请他去100层的房子看看。他走进了这座神奇的房子！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (115,2,'🐭🏠','1到10层住着老鼠一家！小老鼠们在做奶酪、看书、睡觉，每层都不一样。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (115,3,'🐿️🏠','11到20层住着松鼠！松鼠们在摘松果、晾蘑菇、荡秋千，忙得不亦乐乎。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (115,4,'🐸🏠','21到30层住着青蛙！青蛙们在泡澡、唱歌、跳绳，生活好有趣呀。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (115,5,'🦇🏠','越往上走越神奇！住着蜜蜂、啄木鸟、蛇、还有蝙蝠，每十层换一种动物。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (115,6,'☁️🌟','终于到了第100层！原来住着蜘蛛爷爷，他在织最美的星空网。从下到上的旅程真奇妙！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (116,1,'🕳️👧','小女孩不小心掉进了一个洞里，发现地下居然有一座100层的房子！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (116,2,'🐇🏠','1到10层住着兔子一家！兔子们在种萝卜、织毛衣、做运动，地下生活好丰富呀。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (116,3,'🐜🏠','11到20层住着蚂蚁！蚂蚁们在修路、搬食物、开大会，秩序井然。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (116,4,'🐍🏠','21到30层住着蛇！蛇们在泡温泉、量身体、做手工，原来蛇也这么有趣。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (116,5,'🦔🏠','越往下越深！住着刺猬、蜥蜴、鼹鼠，每种动物都有自己独特的地下生活。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (116,6,'💎🌟','到底下第100层，发现了闪闪发光的化石和宝石！地下的世界真奇妙，处处有惊喜！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (117,1,'🌊👧','小女孩坐船出海，船翻了！她沉到海底，发现了一座海底100层的房子！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (117,2,'🐟🏠','1到10层住着海獭！海獭们在敲贝壳、铺海藻床、抱在一起睡觉，太可爱了。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (117,3,'🦀🏠','11到20层住着螃蟹！螃蟹们在横着走路比赛、堆沙堡、开海鲜派对。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (117,4,'🦑🏠','21到30层住着章鱼！章鱼们八只手同时做不同的事：画画、弹琴、做饭，忙极了。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (117,5,'🐢🏠','越往下越深！住着海马、水母、海龟，每种海洋动物都有自己独特的家。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (117,6,'🫧🌟','到底下第100层，发现了最深最神秘的海底世界！大海里藏着这么多秘密呀！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (118,1,'🪂👧','小女孩被风吹上了天空，发现天上居然有一座100层的房子！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (118,2,'🐦🏠','1到10层住着云雀！云雀们在云朵上唱歌、筑巢、教小鸟飞，歌声真好听。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (118,3,'🦅🏠','11到20层住着老鹰！老鹰们在练飞行、眺望远方、保护天空，可威风了。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (118,4,'🦜🏠','21到30层住着鹦鹉！鹦鹉们在学说各种语言、画彩虹、打扮羽毛，热闹极了。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (118,5,'🦉🏠','越往上越有趣！住着蝙蝠、蜂鸟、猫头鹰，每种鸟都有独特的天空生活。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (118,6,'✨🌟','到第100层，碰到了住在星星上的小仙子！天空的世界真美好，充满了想象和惊喜！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (119,1,'🐛📏','一寸虫小小的，只有一寸长。别的动物都小看它，可一寸虫有自己的本领——它会量东西！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (119,2,'🦜📏','知更鸟让一寸虫量它的尾巴。一寸虫一寸一寸地量："一寸、两寸、三寸……"量得真准！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (119,3,'🦩📏','火烈鸟、巨嘴鸟、鹤都来找一寸虫量身体。一寸虫量得又快又准，大家都很佩服。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (119,4,'🌙📏','夜莺说："量量我的歌有多长！"歌怎么量呢？一寸虫想了一个聪明的办法。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (119,5,'🏃🐛','一寸虫一边假装量歌，一边一步一步地走远了。等夜莺反应过来，一寸虫已经走远啦！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (119,6,'🌟🐛','小小的身体也有大大的智慧！遇到困难动脑筋，再小的人也能保护自己。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (120,1,'👴🕐','金老爷家里有一只钟。有一天他买了一只新钟，可是新钟和旧钟时间不一样！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (120,2,'😟👴','金老爷跑上楼看卧室的钟，又跑下楼看客厅的钟，每只钟显示的时间都不一样！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (120,3,'🏃👴','金老爷从这屋跑到那屋，从楼上跑到楼下，想找到一只准时的钟，可怎么都不一样呢？');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (120,4,'🤔👴','金老爷请钟表师傅来看。师傅说："每只钟都是准的，是你跑来跑去花掉了时间呀！"');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (120,5,'😮👴','金老爷明白了！原来从楼下跑到楼上需要时间，所以每只钟看起来不一样。时间一直在走哦！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (120,6,'⏰😊','金老爷不再纠结了，把所有钟调到了同一时间。时间是最宝贵的，要珍惜每一分钟！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (121,1,'🐻❄️','好饿的小白熊在冰天雪地里走着，肚子咕噜咕噜叫。"好饿好饿呀！"');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (121,2,'☁️🐻','小白熊看到天上飘着一朵云，它张开嘴巴咬了一口——云是甜甜的！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (121,3,'🌈🐻','小白熊又咬了一口彩虹，哇，彩虹是七种味道的！红色是草莓味，黄色是柠檬味！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (121,4,'🎵🐻','小白熊吃了一片飘过来的音乐，音乐在肚子里开起了音乐会，好好玩呀！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (121,5,'✨🐻','小白熊吃了好多神奇的东西，肚子变得鼓鼓的，还闪闪发光！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (121,6,'🏠😊','小白熊吃饱了，开心地回家了。想象让世界变得好神奇，什么都可以变成好吃的！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (122,1,'🥚😢','一颗小小的蛋在草地上迷路了。"我的妈妈在哪里？"小蛋伤心地滚来滚去。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (122,2,'🐢🥚','小蛋滚到乌龟妈妈那里："你是我的妈妈吗？"乌龟妈妈说："我的蛋比你的大呀。"');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (122,3,'🐦🥚','小蛋滚到鸟妈妈那里："你是我的妈妈吗？"鸟妈妈说："我的蛋在窝里，不在草地上呀。"');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (122,4,'🐊🥚','小蛋滚到鳄鱼妈妈那里："你是我的妈妈吗？"鳄鱼妈妈说："我的蛋在沙子里呀。"');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (122,5,'🐸🥚','小蛋滚到池塘边，青蛙妈妈跳过来说："哎呀，那是我的宝贝！"原来小蛋是青蛙的卵！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (122,6,'💕🐸','小蝌蚪从卵里钻出来，找到了妈妈好开心！不管走多远，妈妈一定会来找你的。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (123,1,'👹👀','黑暗中有一个绿色大怪物！它有两只大黄眼睛、一个蓝绿色的长鼻子……');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (123,2,'🟢👹','绿色大怪物越来越近了！它有红色的大嘴巴、紫色的乱头发，好吓人呀！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (123,3,'👉👃','"走开，绿色大怪物！"我们对着怪物喊。怪物的鼻子不见了！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (123,4,'👉👄','"走开，绿色大怪物！"怪物的嘴巴也不见了！怪物正在一点点消失！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (123,5,'👉👀','"走开！"眼睛也不见了！头发也不见了！绿色大怪物越来越小！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (123,6,'🌙😊','绿色大怪物完全消失了！"永远别回来！"其实怪物都是纸老虎，勇敢面对就不害怕了！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (124,1,'👸🎨','色彩王国有一位美丽的女王，她能控制所有的颜色。红色热情奔放，蓝色安静温柔。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (124,2,'😡🔴','有一天红色发脾气了，到处乱跑！天空变成红色，河水变成红色，女王也被红色包围了。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (124,3,'😢🔵','蓝色看到红色发火，伤心地哭了起来。蓝色的眼泪把大地染成了蓝色，大家都很忧愁。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (124,4,'😊🟡','黄色跑过来，温暖地拥抱了蓝色和红色。三种颜色混在一起，变成了美丽的橙色和绿色！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (124,5,'🎨💃','女王跳起舞来，所有的颜色跟着节奏旋转！红的、黄的、蓝的，交织成最美的画。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (124,6,'🌈👸','每种颜色都有自己的情绪，不同的颜色在一起才能画出彩虹！表达自己的情感，世界才更美丽。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (125,1,'🖼️🧍','看这幅画，画里的人在做什么？他们的身体在说什么话呢？');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (125,2,'🙌😊','举着双手的人好像在说"我好开心！"弯着腰的人好像在说"我很累。"身体会说话呢！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (125,3,'🕺💃','跳舞的人身体像弯曲的河流，跑步的人身体像拉满的弓。不同的动作表达不同的心情。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (125,4,'🤗😢','张开双臂的人在说"来抱抱我"，低头捂脸的人在说"我很难过"。你能读懂他们的心情吗？');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (125,5,'🎭🖐️','试试你自己！做个开心的姿势，做个惊讶的表情，你的身体也在说话哦！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (125,6,'🎨👀','学会看身体说话，你就能读懂画里的人在想什么。艺术让我们的眼睛更会观察！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (126,1,'🖼️👀','名画就是很有名的画，很多人喜欢看。今天我们换个角度看名画！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (126,2,'🔍🖼️','走近看，这幅画里有好多小细节！远看是一朵花，近看居然是用好多小点点画出来的！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (126,3,'↪️🖼️','从左边看，画里的人好像在微笑。从右边看，她好像在思考。角度不同，感觉不同！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (126,4,'🔄🖼️','把画倒过来看，山变成了瀑布，树变成了倒影。换个角度，世界大不一样！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (126,5,'🧐🖼️','仔细看这幅画的角落，藏着一只小猫！每幅名画里都有秘密等你发现。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (126,6,'🎨👀','看画就像探险，不同的角度有不同的发现。用心观察，你也能成为小鉴赏家！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (127,1,'〰️👀','线条会说话你信吗？看这条线弯弯曲曲的，它好像在唱歌跳舞。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (127,2,'➡️😤','这条线直直的、硬硬的，它好像很生气很坚定！直线说话的方式是"我一定要这样！"');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (127,3,'🌀😊','这条线圆圆的、软软的，它好像在微笑。弯弯的线说话的方式是"来抱抱我！"');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (127,4,'⚡😨','这条线锯齿形的，尖尖的，它好像被吓到了！锯齿线说话的方式是"啊！"');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (127,5,'🌊😌','这条线像波浪一样轻轻摇晃，它好放松呀。波浪线说话的方式是"好舒服～"');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (127,6,'✏️🎨','每种线条都有自己的性格和情绪。画画的时侯，选对线条就能讲好你的故事！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (128,1,'👧📄','美术课上，老师说画点什么吧。小女孩只在纸上点了一个点，觉得什么都不想画。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (128,2,'🖼️🔴','老师看了看说："请签上你的名字。"第二天，小女孩发现她的点被装在金色的画框里挂起来了！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (128,3,'💭👧','"我可以画比这个更好的点！"小女孩开始画各种颜色的点，大的小的，满满一面墙。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (128,4,'🎨🔴🔵🟡','红的点、蓝的点、大的点、小的点、重叠的点……原来一个点可以变出这么多花样！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (128,5,'👦📄','小男孩说："我画得没你好。"小女孩说："你画一条线看看。"小男孩画了一条弯弯的线。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (128,6,'✨🖊️','"请签上你的名字。"小女孩学会了鼓励别人。从一个点开始，每个人都能创造美丽的艺术！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (129,1,'👃🌸','世界有好多好多味道！花香是甜甜的，雨后泥土的味道是清新的，你闻到了吗？');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (129,2,'🎨👃','画家把味道画进画里！看到这幅画，你能闻到面包刚出炉的香味吗？金黄色就是好闻的味道！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (129,3,'🍋👃','柠檬的味道酸酸的，画家用了亮黄色。咖啡的味道苦苦的，画家用了深棕色。颜色也有味道呢！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (129,4,'🌊👃','大海闻起来是什么味道？咸咸的、湿湿的。画家用蓝绿色画出大海的味道，你闻到了吗？');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (129,5,'🍂👃','秋天的味道是落叶和桂花的香，画家用橘红色和金色来画。每种季节都有自己的味儿。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (129,6,'🎨😊','用鼻子感受世界，再用手画出味道。艺术就是用各种感官去体验和表达美好的事物！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (130,1,'🔵🟡','小蓝和小黄是最好的朋友，他们住在街对面，每天一起玩耍。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (130,2,'😊🔵🟡','有一天他们在学校玩得好开心！放学后又跑到公园里追追跑跑，玩得忘了回家。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (130,3,'🟢🔵🟡','小蓝和小黄抱在一起，结果变成了绿色！他们开心地到处跑，觉得自己变了个样子。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (130,4,'😢🏠','可是蓝爸爸蓝妈妈说："你不是我们的小蓝！"黄爸爸黄妈妈也不认识小黄了。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (130,5,'😢🟢','小蓝和小黄好伤心，他们抱在一起哭了。眼泪流出来，慢慢地，他们又变回了原来的颜色！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (130,6,'❤️🔵🟡','爸爸妈妈终于认出了自己的孩子！大家开心地拥抱在一起，蓝色和黄色混在一起又变成了绿色。不同的颜色在一起能创造新的美丽！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (131,1,'🖍️🌈','蜡笔盒里有好多蜡笔，红橙黄绿青蓝紫，每支蜡笔都能画出漂亮的颜色。只有蜡笔小黑一个人孤零零的。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (131,2,'😔🖤','小黑说："我画出来的东西黑乎乎的，一点都不好看。"其他蜡笔也不让小黑画画。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (131,3,'🤔🖍️','橡皮擦先生说："小黑，你来涂一层黑色吧！"其他蜡笔都觉得奇怪，涂黑色有什么用呢？');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (131,4,'✨🖤','小黑认真地涂了一大片黑色，橡皮擦先生在上面擦出漂亮的图案——哇，出现了美丽的烟花！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (131,5,'🎆🌟','原来黑色底色上能画出最闪亮的烟花！其他蜡笔都看呆了，小黑原来这么厉害！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (131,6,'❤️🖍️','每种颜色都有自己的用处，黑色也不例外！不要小看任何人，每个人都有独特的价值。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (132,1,'🖤🖍️','蜡笔小黑又和大家在一起画画了。这次，蜡笔盒里来了一支新蜡笔——是彩色的铅笔！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (132,2,'✨🖍️','彩色铅笔好神奇，能画出彩虹一样的线条！大家围着彩色铅笔，都想和它一起画。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (132,3,'😊🖍️','小黑和彩色铅笔一起画了一幅画。彩色铅笔画花朵，小黑画花盆，配合得真默契！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (132,4,'🎨✨','他们越画越开心，画了花园、城堡、还有满天的星星。原来不同的画笔一起画，画出来的更美丽！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (132,5,'🤝🖤','小黑不再觉得孤单了，因为他找到了神奇的朋友。每个人都有属于自己的朋友。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (132,6,'🌟❤️','不同的工具、不同的颜色，合作起来就能创造奇迹！和朋友一起创作是最快乐的事。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (133,1,'👦🖍️','阿罗有一支紫色的彩色笔。一天晚上他想去散散步，就画了一条月亮下的路。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (133,2,'🍎🌳','阿罗走着走着饿了，就画了一棵苹果树。可是苹果太高够不着，他又画了一只恐龙来帮忙。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (133,3,'🐉🏃','哎呀，恐龙太吓人了！阿罗赶紧画了一艘船逃走，船在水面上飘呀飘。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (133,4,'🏔️🎈','阿罗画了一座大山，爬到山顶，又画了热气球飞上了天。从空中看，世界好美呀！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (133,5,'🏠😴','阿罗想回家了，他画了一扇门，走进去，就是自己的小房间。他画好被子，准备睡觉了。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (133,6,'🌙✨','阿罗放下彩色笔，安心地睡着了。只要有想象力和一支笔，你就能画出整个世界！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (134,1,'👧🤗','你的身体是属于你自己的！有些地方是隐私部位，别人不可以随便碰。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (134,2,'🚫👋','如果有人要摸你的隐私部位，你要大声说"不行！"然后赶紧告诉爸爸妈妈。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (134,3,'💬👧','妈妈说："如果有人让你不舒服，不管是谁，都要告诉我们。"记住，你可以说不！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (134,4,'🤔👆','医生检查身体是正常的，但必须要有爸爸妈妈在旁边。其他时候，隐私部位不能给别人看或碰。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (134,5,'❤️🏠','如果有人做了让你不舒服的事，那不是你的错！一定要告诉信任的大人。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (134,6,'💪👧','你的身体你做主！学会保护自己的身体，勇敢说"不"，这是最重要的事。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (135,1,'👧🚗','放学了，一个不认识的叔叔说："你妈妈让我来接你，跟我走吧。"');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (135,2,'🤔👧','小女孩想了想，妈妈说过的：不认识的人不能跟他们走！她摇了摇头。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (135,3,'🍬😠','陌生人拿出糖果说："来，吃糖吧，叔叔送你回家。"小女孩说："不用了，谢谢。"');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (135,4,'🏠📞','小女孩跑到保安叔叔那里，请他帮忙打电话给妈妈。妈妈说："我没有让别人去接你！"');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (135,5,'👮‍♂️😊','保安叔叔说："你做得很对！不认识的人不管说什么都不要跟他走。"');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (135,6,'🛡️👧','不管陌生人说什么，都不要跟他走！如果不确定，就找老师或保安帮忙打电话确认。保护自己最重要！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (136,1,'👧😠','阿姨来家里做客，想亲小女孩的脸。可是小女孩不喜欢，她说："请不要亲我。"');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (136,2,'🤔👩','阿姨有点尴尬，妈妈走过来说："她说不愿意就不要亲，要尊重孩子的意愿。"');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (136,3,'💪👧','你的脸和身体是你自己的！不想被亲、不想被抱，都可以大声说不。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (136,4,'👋😊','你可以选择握握手或者挥挥手来打招呼，不一定要亲亲抱抱。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (136,5,'🏠❤️','爸爸妈妈说："不管是谁，你不想被亲就可以拒绝，我们永远支持你。"');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (136,6,'🛡️👧','学会说不，是保护自己的第一步。你的身体你做主，任何人都不能强迫你！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (137,1,'😟🤫','有人说："这是我们之间的秘密，不能告诉别人哦。"可是这个秘密让你不舒服。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (137,2,'🤔👧','妈妈说："让你害怕、难过的秘密不是好秘密，一定要告诉爸爸妈妈。"');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (137,3,'🎈😊','好秘密是开心的，比如生日派对的惊喜！坏秘密是让你害怕、难过的。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (137,4,'🚫🤫','如果有人说"这是我们的秘密，不能告诉任何人"，那一定不是好秘密！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (137,5,'🏠❤️','不管别人怎么威胁你，让你不舒服的秘密一定要告诉信任的大人，那不是你的错。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (137,6,'💪👧','分清好秘密和坏秘密，坏秘密一定要说出来！说出来才能保护自己和朋友。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (138,1,'👦🚗','放学了，一个陌生阿姨说："我认识你妈妈，跟我走吧。"小男孩摇摇头。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (138,2,'🍬😠','陌生阿姨又说："我车里有好多玩具和巧克力哦！"小男孩还是不走。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (138,3,'🐕💡','小男孩想起妈妈教过的：即使认识的人，如果妈妈没提前说过，也不能跟他走。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (138,4,'📞🏫','小男孩跑回学校找老师，请老师打电话给妈妈确认。妈妈说没有让人来接。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (138,5,'👮‍♂️✅','老师表扬了小男孩："你做得太对了！安全第一，不能随便跟别人走。"');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (138,6,'🛡️👦','记住这三条：不跟陌生人走，不吃陌生人的东西，遇到问题找老师或警察！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (139,1,'👧💪','如果有人欺负你，你要勇敢地说出来！你不是软弱的，你有保护自己的力量。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (139,2,'🤜😠','有人推你、打你、骂你，这些都是欺负！被欺负不是你的错，是欺负你的人不对。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (139,3,'🗣️👧','大声喊："停止！不许欺负我！"声音越大越好，让周围的人都能听到。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (139,4,'🏃👧','如果对方比你强壮，赶紧跑开去找大人帮忙。跑开不是胆小，是聪明的做法！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (139,5,'🏠❤️','回家告诉爸爸妈妈发生的事情，不要一个人扛着。大人会帮你解决问题。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (139,6,'💪🛡️','每个人都有不被欺负的权利！勇敢站出来保护自己，也别忘了帮助被欺负的朋友。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (140,1,'🐰🏬','小兔子和妈妈去商场，看到了好多好玩的！小兔子东看看西看看。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (140,2,'😟🐰','一转头，妈妈不见了！小兔子好害怕，到处找妈妈，可是人太多了。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (140,3,'🤔🐰','小兔子想起妈妈说过的话："走丢了不要到处跑，去找穿制服的人帮忙。"');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (140,4,'👮‍♂️🐰','小兔子找到保安叔叔，说："我找不到妈妈了。"保安叔叔安慰她，通过广播找妈妈。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (140,5,'😍🐰👩','妈妈听到了广播跑过来，紧紧抱住小兔子！妈妈说："你做得太棒了！"');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (140,6,'🛡️🐰','走丢了不要慌，记住三个办法：站在原地等、找穿制服的人帮忙、记住爸爸妈妈的电话号码！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (141,1,'🔴🟢🟡','红灯、绿灯、黄灯，三个好朋友站在路口眨眼睛。小朋友们，你们知道它们在说什么吗？');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (141,2,'🔴🛑','红灯亮了眨眨眼——"停一停，停一停！"所有车和人都要停下来等一等。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (141,3,'🟢🚶','绿灯亮了眨眨眼——"走吧走吧！"大家可以安全地过马路了。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (141,4,'🟡⏳','黄灯亮了眨眨眼——"等一等，马上变灯！"不要着急，耐心等一下。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (141,5,'🚸👦','过马路要走斑马线，先看左边再看右边，确认安全再通过。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (141,6,'🚦😊','红绿灯是保护我们安全过马路的好帮手！遵守交通规则，安全出行每一天。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (142,1,'👮‍♂️🐕','警官巴克尔知道好多安全提示，可是每次他在台上讲，小朋友们都打瞌睡，没人听。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (142,2,'😄🐕','后来警犬葛芮雅来了！巴克尔讲安全提示，葛芮雅在旁边表演，小朋友们都笑翻了！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (142,3,'📌🐶','"不要踩地上的东西！"葛芮雅假装踩到钉子跳起来。"不要把图钉放在椅子上！"葛芮雅一坐弹起来！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (142,4,'🏆👏','有葛芮雅的表演，小朋友们把安全提示都记住了！巴克尔和葛芮雅成了最佳搭档。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (142,5,'😟🐕','有一天葛芮雅不在，巴克尔一个人讲，小朋友们又打瞌睡了。安全提示需要有趣的配合！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (142,6,'❤️👮‍♂️🐕','巴克尔和葛芮雅明白了，他们在一起才是最棒的！安全知识很重要，用有趣的方式才能记得牢。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (143,1,'👦🏠','小朋友，你知道怎么保护自己吗？让我们一起学习自我保护的小知识吧！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (143,2,'🚪🔒','一个人在家的时候，不要给陌生人开门！不管他说什么，都不要开门。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (143,3,'📞📱','记住爸爸妈妈的电话号码和110报警电话，遇到危险马上打电话求助。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (143,4,'🚫💊','不要吃不认识的人给的东西，不要拿陌生人的礼物，保护自己要从小事做起。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (143,5,'🆘📢','遇到危险要大声喊"救命！"跑到人多的地方，找穿制服的大人帮忙。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (143,6,'🛡️💪','自我保护是一种能力，要从小培养！记住这些知识，做一个勇敢又聪明的小朋友！');